def quelle_aus_ticket(apps, schema_editor):
    """Bestehende Einträge (nur aus Ticket-Scans) bekommen die Anmeldung bzw. Teilnahme ihres
    Tickets als Quelle, bevor die Bedingung „genau eine Quelle“ gilt."""
